#![allow(
    clippy::disallowed_methods,
    clippy::disallowed_types,
    reason = "the subprocess wrapper owns raw Command construction"
)]

//! Typed subprocess contracts for BigLinux Rust desktop apps.
//!
//! `BigSubprocessSpec` replaces raw `std::process::Command` for any
//! subprocess that crosses an untrusted-input boundary. It enforces:
//!
//! - argv list form (never `sh -c`);
//! - explicit timeout;
//! - explicit stdout/stderr capture mode;
//! - optional binary allow-list.
//!
//! Builder is generated by [`bon`]: required fields are checked at
//! compile time. The display-free `Resolved` value can be inspected in
//! tests without spawning a process. Use
//! [`crate::subprocess::BigSubprocessSpec::run`] for the synchronous spawn path.
//!
//! # Examples
//!
//! ```
//! use big_os_kit::subprocess::{BigSubprocessSpec, BigSubprocessOutputMode};
//! use std::time::Duration;
//!
//! let spec = BigSubprocessSpec::builder()
//!     .program("ffprobe")
//!     .arg("-of")
//!     .arg("json")
//!     .arg("/tmp/file.mp4")
//!     .timeout(Duration::from_secs(10))
//!     .stdout(BigSubprocessOutputMode::Capture)
//!     .build();
//!
//! let resolved = spec.resolved();
//! assert_eq!(resolved.program, "ffprobe");
//! assert_eq!(resolved.argv, vec![
//!     "-of".to_string(),
//!     "json".to_string(),
//!     "/tmp/file.mp4".to_string(),
//! ]);
//! assert_eq!(resolved.timeout_ms, 10_000);
//! ```

use std::collections::HashSet;
use std::ffi::OsString;
use std::os::fd::{AsRawFd, BorrowedFd, OwnedFd};
use std::path::PathBuf;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::time::Duration;

use bon::Builder;
use rustix::process::{Pid, Resource, Rlimit, Signal, getrlimit, kill_process_group, setrlimit};

mod child;

/// How often `run` looks at its cancel flag and observer while the child runs.
/// The child's own end wakes it at once.
const RUN_CHECK_INTERVAL: Duration = Duration::from_millis(100);
pub use child::{BigSubprocessChild, ExitWatch, reap_detached};

/// Capture policy for a subprocess stream.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BigSubprocessOutputMode {
    /// Inherit the parent process stream (logs to terminal/console).
    Inherit,
    /// Capture into memory; available via [`BigSubprocessOutput::stdout`].
    Capture,
    /// Discard.
    Null,
}

/// Allow-list policy for the program (argv\[0\]).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct BigSubprocessAllowList {
    /// Set of program names that may be spawned. An empty set
    /// rejects every spawn, providing a deny-all baseline.
    pub allowed: HashSet<String>,
}

impl BigSubprocessAllowList {
    /// Build an allow-list from an iterator of items.
    #[must_use]
    pub fn new<S, I>(items: I) -> Self
    where
        S: Into<String>,
        I: IntoIterator<Item = S>,
    {
        Self {
            allowed: items.into_iter().map(Into::into).collect(),
        }
    }

    /// Returns `true` when the program is permitted.
    #[must_use]
    pub fn permits(&self, program: &str) -> bool {
        self.allowed.contains(program)
    }
}

/// Default subprocess timeout when caller does not set one explicitly.
pub(crate) const DEFAULT_TIMEOUT: Duration = Duration::from_secs(30);

/// Largest single stdout/stderr capture the runtime will retain.
/// Bounded to avoid OOM on hostile programs that emit unbounded output.
pub(crate) const DEFAULT_MAX_CAPTURE_BYTES: usize = 16 * 1024 * 1024;

/// Typed subprocess spec. argv form, timeout, allow-list. Replaces
/// raw `Command::new` at trust boundaries.
///
/// All fields use owned types so the spec is easy to build in tests and
/// pass across thread boundaries. Construct with [`BigSubprocessSpec::builder`].
///
/// # Examples
///
/// ```
/// use big_os_kit::subprocess::{BigSubprocessSpec, BigSubprocessOutputMode};
/// use std::time::Duration;
///
/// let spec = BigSubprocessSpec::builder()
///     .program("ffprobe")
///     .arg("-of")
///     .arg("json")
///     .arg("/tmp/file.mp4")
///     .timeout(Duration::from_secs(10))
///     .stdout(BigSubprocessOutputMode::Capture)
///     .build();
///
/// let r = spec.resolved();
/// assert_eq!(r.program, "ffprobe");
/// assert_eq!(r.timeout_ms, 10_000);
/// ```
#[allow(
    clippy::allow_attributes_without_reason,
    reason = "bon copies this to the builder it generates, whose own `#[allow]` carries no reason"
)]
#[derive(Debug, Clone, Builder)]
#[builder(start_fn = builder, finish_fn = build)]
pub struct BigSubprocessSpec {
    /// argv\[1..\] tokens. Push via the `.arg()` / `.args()` builder methods.
    #[builder(field)]
    pub(crate) argv: Vec<OsString>,

    /// Environment overrides applied on top of inherit policy.
    #[builder(field)]
    pub(crate) env_overrides: Vec<(OsString, OsString)>,

    /// Owned descriptors whose close-on-exec flag is cleared only in the
    /// intended child immediately before `exec`.
    #[builder(field)]
    pub(crate) inherited_fds: Vec<Arc<OwnedFd>>,

    /// Program (argv\[0\]) to spawn: bytes, since a path may not be UTF-8.
    #[builder(into)]
    pub(crate) program: OsString,

    /// Working directory for the child.
    #[builder(into)]
    pub(crate) cwd: Option<PathBuf>,

    /// When `false`, the parent environment is dropped before applying
    /// overrides; when `true`, only [`desktop_only_variables`] are.
    #[builder(default = true)]
    pub(crate) env_inherit: bool,

    /// Start a program for the person rather than a helper of this process:
    /// it gets [`person_environment`], their own numbers instead of the `C`
    /// this process pinned, below the overrides.
    #[builder(default = false)]
    pub(crate) for_person: bool,

    /// Bytes piped to the child stdin. `None` = no stdin write.
    pub(crate) stdin: Option<Vec<u8>>,

    /// Stdout capture policy. Default: `Capture`.
    #[builder(default = BigSubprocessOutputMode::Capture)]
    pub(crate) stdout: BigSubprocessOutputMode,

    /// Stderr capture policy. Default: `Capture`.
    #[builder(default = BigSubprocessOutputMode::Capture)]
    pub(crate) stderr: BigSubprocessOutputMode,

    /// Maximum runtime before kill + [`BigSubprocessError::Timeout`].
    /// Default: 30 seconds.
    #[builder(default = DEFAULT_TIMEOUT)]
    pub(crate) timeout: Duration,

    /// On Unix, spawn the child in a fresh process group/session using
    /// `setsid(2)`. Long-running transcoders use this so cancellation can
    /// terminate helper grandchildren as well as the direct child. Ignored on
    /// non-Unix platforms.
    ///
    /// Such a child, as any started with a descriptor, a death signal, a
    /// limit or a nice value, keeps only stdio and those given by
    /// [`BigSubprocessSpecBuilder::inherit_fd`]: a library that opened a file
    /// without `O_CLOEXEC` (a GPU render node) does not reach it.
    #[builder(default = false)]
    pub(crate) unix_process_group: bool,

    /// On Unix, ask the kernel to signal the child when this process dies
    /// (`PR_SET_PDEATHSIG`). For a helper that only exists to serve its
    /// parent (a surface it draws, a dialog it shows), outliving the parent
    /// is never right, and closing a pipe cannot be relied on: a parent killed
    /// with `SIGKILL`, or one whose child is wedged, leaves the child behind.
    /// The opposite choice is `unix_process_group`, which is how a daemon that
    /// must survive its caller is started.
    #[builder(default = false)]
    pub(crate) die_with_parent: bool,

    /// On Unix, give the child SIGINT's default disposition even when this
    /// process ignores it, which exec otherwise passes on. For a child that a
    /// SIGINT asks to finish its work, such as `gst-launch-1.0 -e`: a program
    /// started in the background of a script has SIGINT ignored.
    #[builder(default = false)]
    pub(crate) default_interrupt: bool,

    /// Optional Unix address-space ceiling applied in the child before exec.
    /// Existing lower soft/hard limits are never raised.
    pub(crate) max_address_space_bytes: Option<u64>,

    /// Optional Unix per-file write ceiling (`RLIMIT_FSIZE`) applied in the
    /// child before exec. Existing lower soft/hard limits are never raised.
    pub(crate) max_file_size_bytes: Option<u64>,

    /// Optional Unix nice value applied in the child before exec. A caller
    /// already nicer is never made less nice.
    pub(crate) nice: Option<i32>,

    /// Optional allow-list. When set, `try_resolved` rejects programs not
    /// in the list.
    pub(crate) allow: Option<BigSubprocessAllowList>,

    /// Work to finish before the child starts. See [`Self::before_run`].
    #[builder(skip)]
    pub(crate) before_run: Option<BeforeRun>,
}

type BeforeRunFn = dyn Fn(&AtomicBool) -> Result<(), BigSubprocessError> + Send + Sync;

#[derive(Clone)]
pub(crate) struct BeforeRun(Arc<BeforeRunFn>);

impl std::fmt::Debug for BeforeRun {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("BeforeRun")
    }
}

// Accumulator setters on the bon-generated builder for the
// `#[builder(field)]` vec fields, so callers chain `.arg("x").arg("y")`.
impl<S: big_subprocess_spec_builder::State> BigSubprocessSpecBuilder<S> {
    /// Append a single argv token.
    pub fn arg(mut self, value: impl Into<OsString>) -> Self {
        self.argv.push(value.into());
        self
    }

    /// Append multiple argv tokens.
    pub fn args<I, T>(mut self, values: I) -> Self
    where
        I: IntoIterator<Item = T>,
        T: Into<OsString>,
    {
        for v in values {
            self.argv.push(v.into());
        }
        self
    }

    /// Set a single environment override `key=value`.
    pub fn env(mut self, key: impl Into<OsString>, value: impl Into<OsString>) -> Self {
        self.env_overrides.push((key.into(), value.into()));
        self
    }

    /// Authorize one owned descriptor to cross only this subprocess boundary.
    ///
    /// The spec retains ownership through spawn and wait, preventing descriptor
    /// reuse while argv refers to its numeric value.
    pub fn inherit_fd(mut self, fd: OwnedFd) -> Self {
        self.inherited_fds.push(Arc::new(fd));
        self
    }

    /// Convenience: install an allow-list constructed from an iterator.
    pub fn allow_list<I, T>(
        self,
        items: I,
    ) -> BigSubprocessSpecBuilder<big_subprocess_spec_builder::SetAllow<S>>
    where
        I: IntoIterator<Item = T>,
        T: Into<String>,
        S::Allow: big_subprocess_spec_builder::IsUnset,
    {
        self.allow(BigSubprocessAllowList::new(items))
    }
}

impl BigSubprocessSpec {
    /// Validate and resolve. Errors when the program is empty or fails
    /// the allow-list.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::EmptyProgram`] when the program string is empty,
    /// or [`BigSubprocessError::ProgramNotAllowed`] when an allow-list is set and the
    /// program is missing from it.
    pub fn try_resolved(&self) -> Result<BigSubprocessResolved, BigSubprocessError> {
        self.validate()?;
        Ok(BigSubprocessResolved {
            program: self.program.to_string_lossy().into_owned(),
            argv: self
                .argv
                .iter()
                .map(|s| s.to_string_lossy().into_owned())
                .collect(),
            cwd: self.cwd.clone(),
            env_overrides: self
                .env_overrides
                .iter()
                .map(|(k, v)| {
                    (
                        k.to_string_lossy().into_owned(),
                        v.to_string_lossy().into_owned(),
                    )
                })
                .collect(),
            env_inherit: self.env_inherit,
            for_person: self.for_person,
            stdin_len: self.stdin.as_ref().map(Vec::len).unwrap_or(0),
            inherited_fd_count: self.inherited_fds.len(),
            stdout: self.stdout,
            stderr: self.stderr,
            timeout_ms: u64::try_from(self.timeout.as_millis()).unwrap_or(u64::MAX),
            unix_process_group: self.unix_process_group,
            die_with_parent: self.die_with_parent,
            default_interrupt: self.default_interrupt,
            max_address_space_bytes: self.max_address_space_bytes,
            max_file_size_bytes: self.max_file_size_bytes,
        })
    }

    /// The checks of [`Self::try_resolved`], without building its copies.
    fn validate(&self) -> Result<(), BigSubprocessError> {
        if self.program.is_empty() {
            return Err(BigSubprocessError::EmptyProgram);
        }
        let mut tokens = std::iter::once(&self.program).chain(&self.argv);
        if let Some(index) = tokens.position(|token| token.as_encoded_bytes().contains(&0)) {
            return Err(BigSubprocessError::ForbiddenArgvByte { index, byte: 0 });
        }
        if let Some(list) = &self.allow
            && !self
                .program
                .to_str()
                .is_some_and(|program| list.permits(program))
        {
            return Err(BigSubprocessError::ProgramNotAllowed(
                self.program.to_string_lossy().into_owned(),
            ));
        }
        Ok(())
    }

    /// Resolve, panicking on invalid spec. Use in tests and contexts where
    /// the spec is statically known to be valid.
    ///
    /// # Panics
    ///
    /// Panics if [`Self::try_resolved`] returns an error.
    #[must_use]
    #[expect(
        clippy::expect_used,
        reason = "panics by contract: `try_resolved` is the fallible form"
    )]
    pub fn resolved(&self) -> BigSubprocessResolved {
        self.try_resolved()
            .expect("BigSubprocessSpec must validate")
    }

    /// Run `prepare` before every start of this spec, with the cancel flag of
    /// the run (a flag never set for [`Self::spawn`] and
    /// [`Self::spawn_detached`]). Its error ends the run and the child never
    /// starts: a connection the command rides on is set up here, where a
    /// cancel reaches it.
    #[must_use]
    pub fn before_run(
        mut self,
        prepare: impl Fn(&AtomicBool) -> Result<(), BigSubprocessError> + Send + Sync + 'static,
    ) -> Self {
        self.before_run = Some(BeforeRun(Arc::new(prepare)));
        self
    }

    /// Signal the child when this process dies (see the `die_with_parent`
    /// field). The kernel ties it to the thread that starts the child, so run
    /// the spec from a thread that stays until the child is done.
    #[must_use]
    pub fn die_with_parent(mut self) -> Self {
        self.die_with_parent = true;
        self
    }

    fn prepare(&self, cancel: &AtomicBool) -> Result<(), BigSubprocessError> {
        match &self.before_run {
            Some(prepare) => (prepare.0)(cancel),
            None => Ok(()),
        }
    }

    /// Spawn the subprocess synchronously and wait for completion.
    ///
    /// Captures stdout/stderr if their modes are [`BigSubprocessOutputMode::Capture`].
    /// Returns when the child exits or when the timeout elapses, whichever first.
    /// On timeout the child is killed and [`BigSubprocessError::Timeout`] is returned.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::Spawn`] if the process cannot be started,
    /// [`BigSubprocessError::Io`] on stream I/O errors,
    /// or [`BigSubprocessError::Timeout`] if the configured timeout elapses.
    pub fn run(&self) -> Result<BigSubprocessOutput, BigSubprocessError> {
        // Never-set cancel flag: identical timeout/exit behavior to the
        // cancellable path, so both share one drain/kill loop.
        self.run_cancellable(&AtomicBool::new(false))
    }

    /// Spawn the subprocess synchronously and wait, honoring an external
    /// cancellation flag in addition to the spec timeout.
    ///
    /// Behaves exactly like [`Self::run`] (same concurrent stdout/stderr
    /// draining, same timeout-kill path), but the wait loop also breaks when
    /// `cancel` becomes `true`. On cancellation the child is killed (the same
    /// kill path as timeout) and [`BigSubprocessError::Cancelled`] is returned.
    ///
    /// The flag is polled every 100 ms with the deadline, so a
    /// flipped `cancel` terminates the child within one tick regardless of the
    /// spec timeout. Share the flag with the UI thread (e.g. `Arc<AtomicBool>`
    /// flipped on component teardown) to bind a subprocess to a widget
    /// lifetime; see
    /// [`big_relm4_components::task`](../../big_relm4_components/task/index.html)
    /// for the Relm4-bound helper.
    ///
    /// # Errors
    ///
    /// As [`Self::run`], plus [`BigSubprocessError::Cancelled`] when `cancel`
    /// is set before the child exits.
    pub fn run_cancellable(
        &self,
        cancel: &AtomicBool,
    ) -> Result<BigSubprocessOutput, BigSubprocessError> {
        self.validate()?;
        self.prepare(cancel)?;
        run_validated(self, cancel, None)
    }

    /// Spawn the subprocess synchronously and observe external progress while
    /// honoring cancellation and the configured timeout.
    ///
    /// `observe` runs on the calling worker thread at the same cadence as
    /// cancellation polling. It is intended for progress that is safer to
    /// measure outside a child process than to parse from human-facing output,
    /// such as the size of a private staging file. Returning an I/O error stops
    /// and reaps the child before returning that error.
    ///
    /// # Errors
    ///
    /// As [`Self::run_cancellable`], plus [`BigSubprocessError::Io`] when the
    /// observer fails.
    pub fn run_cancellable_observed(
        &self,
        cancel: &AtomicBool,
        mut observe: impl FnMut() -> std::io::Result<()>,
    ) -> Result<BigSubprocessOutput, BigSubprocessError> {
        self.validate()?;
        self.prepare(cancel)?;
        run_validated(self, cancel, Some(&mut observe))
    }

    /// Spawn the subprocess without waiting and return a
    /// [`BigSubprocessChild`] handle for streaming and lifecycle control.
    ///
    /// Use this for long-running children (media players, transcoders,
    /// daemons) that out-live a single `run()` call or whose output must be
    /// consumed incrementally. argv / allow-list / forbidden-byte
    /// validation applies exactly as in [`Self::run`], but the spec
    /// `timeout` is not enforced: the caller owns the child's lifetime
    /// via the returned handle.
    ///
    /// stdin/stdout/stderr follow the spec's modes; piped streams are
    /// exposed via [`BigSubprocessChild::take_stdout`] / `take_stderr` /
    /// `take_stdin`. Any `stdin` payload set on the spec is not
    /// auto-written here.
    ///
    /// # Errors
    ///
    /// Returns [`BigSubprocessError::EmptyProgram`],
    /// [`BigSubprocessError::ProgramNotAllowed`], or
    /// [`BigSubprocessError::ForbiddenArgvByte`] on validation failure, or
    /// [`BigSubprocessError::Spawn`] if the process cannot be started.
    pub fn spawn(&self) -> Result<BigSubprocessChild, BigSubprocessError> {
        self.validate()?;
        self.prepare(&AtomicBool::new(false))?;
        let child = build_command(self)
            .spawn()
            .map_err(BigSubprocessError::Spawn)?;
        Ok(BigSubprocessChild::new(child, self.unix_process_group))
    }

    /// Spawn fully detached (fire-and-forget) for launching helper programs
    /// (`xdg-open`, an external editor) where the parent neither reads
    /// output nor waits.
    ///
    /// stdin/stdout/stderr are redirected to null regardless of the spec's
    /// capture modes. The child is handed to the process-wide detached-child
    /// reaper, so fire-and-forget launches do not consume one waiter thread per
    /// child and do not leave zombies behind. Validation applies as in [`Self::spawn`].
    ///
    /// # Errors
    ///
    /// As [`Self::spawn`].
    pub fn spawn_detached(&self) -> Result<(), BigSubprocessError> {
        use std::process::Stdio;
        self.validate()?;
        self.prepare(&AtomicBool::new(false))?;
        let mut cmd = build_command(self);
        cmd.stdin(Stdio::null());
        cmd.stdout(Stdio::null());
        cmd.stderr(Stdio::null());
        let child = cmd.spawn().map_err(BigSubprocessError::Spawn)?;
        reap_detached(BigSubprocessChild::new(child, self.unix_process_group));
        Ok(())
    }
}

/// Display-free view of a resolved subprocess spec.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BigSubprocessResolved {
    /// Validated program (argv\[0\]).
    pub program: String,
    /// argv\[1..\] tokens as strings.
    pub argv: Vec<String>,
    /// Working directory, if explicitly set.
    pub cwd: Option<PathBuf>,
    /// Environment overrides resolved to strings.
    pub env_overrides: Vec<(String, String)>,
    /// Inherits the parent environment when `true`; set `false` for
    /// reproducible builds and to keep host secrets out of child procs.
    pub env_inherit: bool,
    /// Starts a program for the person ([`person_environment`]).
    pub for_person: bool,
    /// Length of the stdin payload (0 = none).
    pub stdin_len: usize,
    /// Number of explicitly inherited Unix descriptors; descriptor numbers
    /// and contents are absent from this inspectable view.
    inherited_fd_count: usize,
    /// Stdout capture policy.
    pub stdout: BigSubprocessOutputMode,
    /// Stderr capture policy.
    pub stderr: BigSubprocessOutputMode,
    /// Timeout in milliseconds.
    pub timeout_ms: u64,
    /// Whether Unix children are spawned in a fresh process group/session.
    pub unix_process_group: bool,
    /// Whether the kernel ends the child when this process dies.
    pub die_with_parent: bool,
    /// Whether the child gets SIGINT's default disposition back.
    pub default_interrupt: bool,
    /// Optional Unix address-space ceiling in bytes.
    pub max_address_space_bytes: Option<u64>,
    /// Optional Unix per-file write ceiling in bytes (`RLIMIT_FSIZE`).
    pub max_file_size_bytes: Option<u64>,
}

/// Result of a completed subprocess run.
#[derive(Debug, Clone)]
pub struct BigSubprocessOutput {
    /// Exit status.
    pub status: BigSubprocessStatus,
    /// Captured stdout bytes (empty when stdout mode is not `Capture`).
    pub stdout: Vec<u8>,
    /// stdout went past the capture limit: `stdout` holds only its first
    /// bytes. A parser that needs the whole output refuses it.
    pub stdout_truncated: bool,
    /// Captured stderr bytes (empty when stderr mode is not `Capture`).
    pub stderr: Vec<u8>,
}

impl BigSubprocessOutput {
    /// stdout as lossy UTF-8.
    #[must_use]
    pub fn stdout_lossy(&self) -> String {
        String::from_utf8_lossy(&self.stdout).into_owned()
    }

    /// stderr as lossy UTF-8.
    #[must_use]
    pub fn stderr_lossy(&self) -> String {
        String::from_utf8_lossy(&self.stderr).into_owned()
    }
}

/// Exit outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BigSubprocessStatus {
    /// Process exited with the given status code (or `None` on signal exit).
    Exited(Option<i32>),
}

impl BigSubprocessStatus {
    /// `true` when the child returned exit code 0.
    #[must_use]
    pub fn success(self) -> bool {
        matches!(self, Self::Exited(Some(0)))
    }

    /// Exit code, or `None` when the child was terminated by a signal.
    /// Mirrors `std::process::ExitStatus::code`.
    #[must_use]
    pub fn code(self) -> Option<i32> {
        match self {
            Self::Exited(code) => code,
        }
    }
}

/// Failure modes when validating or running a subprocess spec.
#[derive(Debug, thiserror::Error)]
pub enum BigSubprocessError {
    /// Program field is empty.
    #[error("subprocess program is empty")]
    EmptyProgram,
    /// Program rejected by allow-list.
    #[error("program not in allow-list: {0:?}")]
    ProgramNotAllowed(String),
    /// `std::process::Command::spawn` failed.
    #[error("failed to spawn: {0}")]
    Spawn(#[source] std::io::Error),
    /// I/O error while reading stdout/stderr or writing stdin.
    #[error("subprocess i/o error: {0}")]
    Io(#[source] std::io::Error),
    /// Configured timeout elapsed before the child exited.
    #[error("subprocess timed out")]
    Timeout,
    /// External cancellation flag was set before the child exited. The child
    /// was killed on the same path as [`Self::Timeout`].
    #[error("subprocess cancelled")]
    Cancelled,
    /// argv token contains NUL, which ends a C string, so the child would
    /// see it cut short. Every other byte, newline included, is legal in a
    /// Linux file name and passes; whoever logs argv escapes it.
    #[error("argv token at index {index} contains forbidden control byte 0x{byte:02x}")]
    ForbiddenArgvByte {
        /// `0` for program, `1..` for argv\[i-1\].
        index: usize,
        /// Offending byte.
        byte: u8,
    },
}

fn stdio_for(mode: BigSubprocessOutputMode) -> std::process::Stdio {
    use std::process::Stdio;
    match mode {
        BigSubprocessOutputMode::Inherit => Stdio::inherit(),
        BigSubprocessOutputMode::Capture => Stdio::piped(),
        BigSubprocessOutputMode::Null => Stdio::null(),
    }
}

/// Whether `program` is installed: an executable file on `PATH`, or the
/// executable file it names when it contains a `/`.
///
/// [`BigSubprocessSpec::try_resolved`] validates a name and an allow list and
/// never touches the filesystem, so it says yes for a program that is not
/// installed. A menu that offers an action only when its program exists ("Use
/// as wallpaper", which lives in another package) has to ask this instead,
/// or it offers an item that can only fail after the click.
#[must_use]
pub fn program_on_path(program: &str) -> bool {
    if program.contains('/') {
        return crate::file_io::is_executable_file(std::path::Path::new(program));
    }
    find_program(program).is_some()
}

/// The absolute path `program` runs from: itself when it is an absolute path,
/// otherwise the first executable of that name in an absolute `PATH` entry.
///
/// A relative entry (`.`, an empty one, `bin`) names a different directory
/// for every working directory, so a program started inside a project would
/// run that project's file of the same name. Those entries are skipped.
#[must_use]
pub fn find_program(program: &str) -> Option<std::path::PathBuf> {
    find_program_in(program, &std::env::var_os("PATH")?)
}

/// [`find_program`] against the given `PATH` value.
#[must_use]
pub fn find_program_in(program: &str, path: &std::ffi::OsStr) -> Option<std::path::PathBuf> {
    if program.is_empty() {
        return None;
    }
    if program.contains('/') {
        let program = std::path::Path::new(program);
        return (program.is_absolute() && crate::file_io::is_executable_file(program))
            .then(|| program.to_path_buf());
    }
    std::env::split_paths(path)
        .filter(|dir| dir.is_absolute())
        .map(|dir| dir.join(program))
        .find(|candidate| crate::file_io::is_executable_file(candidate))
}

/// Set by big-host beside `GSK_RENDERER` when it chose GTK's renderer for the
/// desktop alone: GL, after a hang out of video memory on Vulkan.
pub const DESKTOP_RENDERER: &str = "BIG_HOST_GSK_RENDERER";

/// Set by the session beside the GPU variables of the desktop's own processes
/// (bigshell-session): Mesa's EGL and no NVIDIA Vulkan driver on a machine whose
/// screens a Mesa driver draws while an NVIDIA GPU waits for programs that ask
/// for it, and no lavapipe beside a GPU with a Vulkan driver of its own.
pub const DESKTOP_GPU: &str = "BIG_DESKTOP_GPU";

/// Whether this process's environment asks Mesa to draw on the processor
/// (`LIBGL_ALWAYS_SOFTWARE`), as Mesa reads it: headless-gate asks, and so
/// may a person. Mesa's EGL then lists only its software device, but another
/// vendor's EGL still lists its GPU, and Mesa refuses a hardware device
/// asked for by name.
#[must_use]
pub fn software_rendering_requested() -> bool {
    mesa_true(std::env::var_os("LIBGL_ALWAYS_SOFTWARE").as_deref())
}

/// `value` read as Mesa's `debug_parse_bool_option` reads a boolean
/// variable whose default is false: `1`, `y`, `yes`, `t` and `true` in any
/// case are true, anything else false.
fn mesa_true(value: Option<&std::ffi::OsStr>) -> bool {
    value.is_some_and(|value| {
        value == "1"
            || ["y", "yes", "t", "true"]
                .iter()
                .any(|word| value.eq_ignore_ascii_case(word))
    })
}

const DESKTOP_GPU_VARIABLES: [&str; 3] = [
    "__EGL_VENDOR_LIBRARY_FILENAMES",
    "VK_LOADER_DRIVERS_DISABLE",
    DESKTOP_GPU,
];

/// The soft limits a host process inherited, as `NOFILE CORE`, each a number
/// or `-` when unchanged ([`export_inherited_limits`]). A module library links
/// its own copy of this crate, whose record of them the host never set.
const INHERITED_LIMITS: &str = "BIG_HOST_INHERITED_LIMITS";

/// The variables of this process's environment that the programs it starts
/// must not inherit: the socket its systemd unit waits on for
/// [`crate::service_ready::notify`], which speaks for this process alone, the
/// limits it inherited, which they get as limits instead, the PID of its
/// pressure watcher ([`crate::pressure_protocol::PROCESS_WATCHER`]), the
/// person's numeric locale it kept ([`person_environment`]), a renderer
/// big-host chose for itself, so a GTK program started from the desktop keeps
/// GTK's own choice, and the desktop's GPU variables ([`DESKTOP_GPU`]), so
/// `prime-run` and `PrefersNonDefaultGPU` still reach the NVIDIA GPU.
#[must_use]
pub fn desktop_only_variables() -> Vec<&'static str> {
    let mut variables = vec![
        "NOTIFY_SOCKET",
        INHERITED_LIMITS,
        crate::pressure_protocol::PROCESS_WATCHER,
        crate::process_locale::PERSON_NUMERIC_LOCALE,
    ];
    if std::env::var_os(DESKTOP_RENDERER).is_some() {
        variables.extend(["GSK_RENDERER", DESKTOP_RENDERER]);
    }
    if std::env::var_os(DESKTOP_GPU).is_some() {
        variables.extend(DESKTOP_GPU_VARIABLES);
    }
    variables
}

/// The environment of a program started for the person, as changes to this
/// process's: each variable with its value, or `None` to remove it. The
/// [`desktop_only_variables`] go, and once [`crate::init_c_numeric_locale`]
/// pinned numbers to `C`, `LC_NUMERIC` is the person's again, removed when
/// they named none.
///
/// Only this gives the person's numbers back: a program started any other way
/// inherits `LC_NUMERIC=C`, and, unless it lost the [`desktop_only_variables`],
/// the variable that keeps the person's value.
#[must_use]
pub fn person_environment() -> Vec<(&'static str, Option<OsString>)> {
    let mut changes: Vec<_> = desktop_only_variables()
        .into_iter()
        .map(|name| (name, None))
        .collect();
    if let Some(numeric) = std::env::var_os(crate::process_locale::PERSON_NUMERIC_LOCALE) {
        changes.push((
            "LC_NUMERIC",
            Some(numeric).filter(|value| !value.is_empty()),
        ));
    }
    changes
}

/// The desktop's GPU variables this process has, for a process of the
/// desktop's own that gets them only explicitly: the compositor, started
/// through this module, and Xwayland, started with a cleared environment.
#[must_use]
pub fn desktop_gpu_environment() -> Vec<(&'static str, std::ffi::OsString)> {
    if std::env::var_os(DESKTOP_GPU).is_none() {
        return Vec::new();
    }
    DESKTOP_GPU_VARIABLES
        .into_iter()
        .filter_map(|name| Some((name, std::env::var_os(name)?)))
        .collect()
}

/// The open-file soft limit this process inherited, once [`raise_file_limit`]
/// raised it; 0 before.
static INHERITED_FILE_LIMIT: AtomicU64 = AtomicU64::new(0);
/// The core size soft limit this process inherited, when [`lower_core_limit`]
/// set it to nothing; 0 otherwise, since a limit of 0 is never lowered.
static INHERITED_CORE_LIMIT: AtomicU64 = AtomicU64::new(0);

/// Set this process's core size soft limit to nothing, keeping the inherited
/// one for the programs it starts ([`give_back_limits`], [`restore_limits`]).
pub(crate) fn lower_core_limit() {
    let limit = getrlimit(Resource::Core);
    let inherited = raw_limit(limit.current);
    if inherited == 0 {
        return;
    }
    let lowered = Rlimit {
        current: Some(0),
        maximum: limit.maximum,
    };
    if setrlimit(Resource::Core, lowered).is_ok() {
        INHERITED_CORE_LIMIT.store(inherited, Ordering::Relaxed);
    }
}

/// A limit as the kernel spells it: no limit is `u64::MAX`, which it also
/// reads back as no limit.
fn raw_limit(limit: Option<u64>) -> u64 {
    limit.unwrap_or(u64::MAX)
}

/// The soft limits to give back to a started program: open files and core
/// size, each when this process changed it, by this copy of the crate or by
/// the host's ([`export_inherited_limits`]).
fn inherited_limits() -> [(Resource, Option<u64>); 2] {
    let file = INHERITED_FILE_LIMIT.load(Ordering::Relaxed);
    let core = INHERITED_CORE_LIMIT.load(Ordering::Relaxed);
    if file == 0
        && core == 0
        && let Some(exported) = std::env::var(INHERITED_LIMITS)
            .ok()
            .and_then(|value| parse_inherited_limits(&value))
    {
        return exported;
    }
    [
        (Resource::Nofile, (file != 0).then_some(file)),
        (Resource::Core, (core != 0).then_some(core)),
    ]
}

/// [`INHERITED_LIMITS`] read back; `None` when it is not two fields.
fn parse_inherited_limits(value: &str) -> Option<[(Resource, Option<u64>); 2]> {
    let limit = |field: &str| match field {
        "-" => Some(None),
        number => number.parse().ok().map(Some),
    };
    let (file, core) = value.split_once(' ')?;
    Some([
        (Resource::Nofile, limit(file)?),
        (Resource::Core, limit(core)?),
    ])
}

/// Publish the soft limits [`raise_file_limit`] and `lower_core_limit`
/// changed, so the module libraries this process loads give them back to the
/// programs they start too.
///
/// # Safety
///
/// No other thread may be running: it sets an environment variable.
pub unsafe fn export_inherited_limits() {
    let [(_, file), (_, core)] = inherited_limits();
    if file.is_none() && core.is_none() {
        return;
    }
    let field =
        |limit: Option<u64>| limit.map_or_else(|| "-".to_owned(), |limit| limit.to_string());
    // SAFETY: the caller runs this before any other thread exists.
    unsafe { std::env::set_var(INHERITED_LIMITS, format!("{} {}", field(file), field(core))) };
}

/// Raise this process's open-file soft limit to its hard limit.
///
/// Mesa's Vulkan WSI takes three descriptors for each frame it acquires and
/// reports running out as `VK_ERROR_OUT_OF_DEVICE_MEMORY`, after which GTK
/// holds the main loop for good. The programs the desktop starts get the
/// inherited limit back ([`restore_limits`]): one built on `select()`
/// breaks on a descriptor past 1023.
pub fn raise_file_limit() {
    let limit = getrlimit(Resource::Nofile);
    let inherited = raw_limit(limit.current);
    if inherited >= raw_limit(limit.maximum) {
        return;
    }
    let raised = Rlimit {
        current: limit.maximum,
        maximum: limit.maximum,
    };
    if setrlimit(Resource::Nofile, raised).is_ok() {
        INHERITED_FILE_LIMIT.store(inherited, Ordering::Relaxed);
    }
}

/// Have the program `cmd` starts begin with the soft limits this process
/// inherited, where it changed them ([`raise_file_limit`],
/// `lower_core_limit`): set between fork and exec, so the program never sees
/// this process's own. [`restore_limits`] is for what was started some other
/// way.
pub fn give_back_limits(cmd: &mut std::process::Command) {
    use std::os::unix::process::CommandExt;
    let limits = inherited_limits();
    if limits.iter().all(|(_, inherited)| inherited.is_none()) {
        return;
    }
    // SAFETY: the closure runs between fork and exec and makes only the
    // getrlimit and setrlimit system calls, which allocate nothing.
    unsafe {
        cmd.pre_exec(move || {
            for (resource, inherited) in limits {
                let Some(inherited) = inherited else {
                    continue;
                };
                let limit = getrlimit(resource);
                let given_back = Rlimit {
                    current: Some(inherited.min(raw_limit(limit.maximum))),
                    maximum: limit.maximum,
                };
                setrlimit(resource, given_back)?;
            }
            Ok(())
        });
    }
}

/// Give `pid`, a program this process started, the soft limits this process
/// inherited, where it changed them.
pub fn restore_limits(pid: u32) {
    let Ok(pid) = libc::pid_t::try_from(pid) else {
        return;
    };
    for (resource, inherited) in inherited_limits() {
        let Some(inherited) = inherited else {
            continue;
        };
        let resource = resource as libc::__rlimit_resource_t;
        let mut limit = libc::rlimit {
            rlim_cur: 0,
            rlim_max: 0,
        };
        // SAFETY: a null new limit only reads `pid`'s limits into a valid local value.
        if unsafe { libc::prlimit(pid, resource, std::ptr::null(), &raw mut limit) } != 0 {
            continue;
        }
        limit.rlim_cur = inherited.min(limit.rlim_max);
        // SAFETY: sets only the soft limit of a child of this process; a child
        // gone meanwhile makes the call fail, which changes nothing.
        unsafe { libc::prlimit(pid, resource, &raw const limit, std::ptr::null_mut()) };
    }
}

/// Build the `std::process::Command` for a spec: argv form, cwd, env
/// policy, and the configured stdin/stdout/stderr modes. Shared by the
/// blocking [`BigSubprocessSpec::run`] and the streaming
/// [`BigSubprocessSpec::spawn`] paths so both honor the same contract.
fn build_command(spec: &BigSubprocessSpec) -> std::process::Command {
    use std::process::{Command, Stdio};

    let mut cmd = Command::new(&spec.program);
    cmd.args(&spec.argv);
    if let Some(dir) = &spec.cwd {
        cmd.current_dir(dir);
    }
    if spec.env_inherit {
        for key in desktop_only_variables() {
            cmd.env_remove(key);
        }
    } else {
        cmd.env_clear();
    }
    if spec.for_person {
        for (key, value) in person_environment() {
            match value {
                Some(value) => cmd.env(key, value),
                None => cmd.env_remove(key),
            };
        }
    }
    for (k, v) in &spec.env_overrides {
        cmd.env(k, v);
    }
    cmd.stdin(if spec.stdin.is_some() {
        Stdio::piped()
    } else {
        Stdio::null()
    });
    cmd.stdout(stdio_for(spec.stdout));
    cmd.stderr(stdio_for(spec.stderr));
    #[cfg(unix)]
    if spec.unix_process_group
        || spec.die_with_parent
        || spec.default_interrupt
        || spec.max_address_space_bytes.is_some()
        || spec.max_file_size_bytes.is_some()
        || spec.nice.is_some()
        || !spec.inherited_fds.is_empty()
    {
        use std::os::unix::process::CommandExt;
        let unix_process_group = spec.unix_process_group;
        let die_with_parent = spec.die_with_parent;
        let parent = rustix::process::getpid();
        let default_interrupt = spec.default_interrupt;
        let max_address_space_bytes = spec.max_address_space_bytes;
        let max_file_size_bytes = spec.max_file_size_bytes;
        let nice = spec.nice;
        let inherited_fds = spec
            .inherited_fds
            .iter()
            .map(|fd| fd.as_raw_fd())
            .collect::<Vec<_>>();
        // SAFETY: the closure runs between fork and exec and makes only
        // async-signal-safe calls (setsid, close_range, prctl, sigaction,
        // rlimits, setpriority).
        unsafe {
            cmd.pre_exec(move || {
                // Only stdio and the descriptors given by `inherit_fd`, opened
                // again below, cross exec: a library that opened a file without
                // O_CLOEXEC (a GPU render node, a socket) does not reach the
                // child. Marked close-on-exec, left open: std's exec error pipe
                // is among them. A kernel before 5.11 lacks the call, and there
                // the child inherits what exec passes on.
                let first: libc::c_uint = 3;
                if libc::syscall(
                    libc::SYS_close_range,
                    first,
                    libc::c_uint::MAX,
                    libc::CLOSE_RANGE_CLOEXEC,
                ) < 0
                {
                    let error = std::io::Error::last_os_error();
                    if error.raw_os_error() != Some(libc::ENOSYS) {
                        return Err(error);
                    }
                }
                if unix_process_group {
                    rustix::process::setsid()?;
                }
                if die_with_parent {
                    // Set before the check below, and checked after: the
                    // parent may already have died between fork and here, and
                    // then no signal is ever coming.
                    // An orphan goes to init or to the session's subreaper
                    // (`systemd --user`), so only the parent's own id tells.
                    rustix::process::set_parent_process_death_signal(Some(Signal::TERM))?;
                    if rustix::process::getppid() != Some(parent) {
                        libc::_exit(0);
                    }
                }
                if default_interrupt {
                    let mut action: libc::sigaction = std::mem::zeroed();
                    action.sa_sigaction = libc::SIG_DFL;
                    #[expect(
                        clippy::disallowed_methods,
                        reason = "kept: the child takes back the default action before exec"
                    )]
                    let reset =
                        libc::sigaction(libc::SIGINT, &raw const action, std::ptr::null_mut());
                    if reset < 0 {
                        return Err(std::io::Error::last_os_error());
                    }
                }
                if let Some(max_bytes) = max_address_space_bytes {
                    constrain_current_worker_process(max_bytes)?;
                }
                if let Some(max_bytes) = max_file_size_bytes {
                    lower_file_size_limit(max_bytes)?;
                }
                // The child has a single thread: `who` 0 is the process.
                if let Some(nice) = nice
                    && rustix::process::getpriority_process(None)? < nice
                {
                    rustix::process::setpriority_process(None, nice)?;
                }
                for fd in &inherited_fds {
                    // SAFETY: the child's copy of a descriptor the spec holds
                    // open until spawn returns.
                    let fd = BorrowedFd::borrow_raw(*fd);
                    rustix::io::fcntl_setfd(fd, rustix::io::FdFlags::empty())?;
                }
                Ok(())
            });
        }
    }
    give_back_limits(&mut cmd);
    cmd
}

/// Lower this process's soft address-space limit without ever raising an
/// existing soft or hard limit.
///
/// A spawned child applies this before it parses untrusted input, so an
/// oversized allocation aborts only the child.
///
/// # Errors
///
/// Returns the operating-system error from `getrlimit` or `setrlimit`.
#[cfg(unix)]
fn constrain_current_worker_process(max_bytes: u64) -> std::io::Result<()> {
    let limit = getrlimit(Resource::As);
    let bounded = Rlimit {
        current: Some(bounded_worker_soft_limit(
            raw_limit(limit.current),
            raw_limit(limit.maximum),
            max_bytes,
        )),
        maximum: limit.maximum,
    };
    setrlimit(Resource::As, bounded)?;
    // Both core limits to nothing: this helper is about to read secrets. The
    // limit crosses exec; `PR_SET_DUMPABLE` would not, as exec resets it.
    let no_core = Rlimit {
        current: Some(0),
        maximum: Some(0),
    };
    setrlimit(Resource::Core, no_core)?;
    Ok(())
}

#[cfg(unix)]
fn bounded_worker_soft_limit(current: u64, hard: u64, requested: u64) -> u64 {
    requested.min(current).min(hard)
}

#[cfg(unix)]
fn lower_file_size_limit(max_bytes: u64) -> std::io::Result<()> {
    let limit = getrlimit(Resource::Fsize);
    let lowered = |value: Option<u64>| Some(raw_limit(value).min(max_bytes));
    let lowered = Rlimit {
        current: lowered(limit.current),
        maximum: lowered(limit.maximum),
    };
    Ok(setrlimit(Resource::Fsize, lowered)?)
}

/// Why the wait loop stopped: normal exit, deadline, external cancel, or a
/// failed `try_wait` or observer. Cancel and timeout share the same kill path
/// but map to distinct errors.
enum WaitOutcome {
    Exited(std::process::ExitStatus),
    TimedOut,
    Cancelled,
    Failed(std::io::Error),
}

fn run_validated(
    spec: &BigSubprocessSpec,
    cancel: &AtomicBool,
    mut observer: Option<&mut dyn FnMut() -> std::io::Result<()>>,
) -> Result<BigSubprocessOutput, BigSubprocessError> {
    use std::io::Write;

    let mut cmd = build_command(spec);
    let mut child = cmd.spawn().map_err(BigSubprocessError::Spawn)?;

    // Drain stdout/stderr on dedicated threads. A child that writes more than
    // the OS pipe buffer (~64 KiB) blocks on write until a reader consumes it;
    // draining only after the child exited would run every large-output
    // subprocess (`pw-dump` writes ~300 KiB) to the timeout.
    //
    // Each sends its bytes when its pipe closes, so the call can stop waiting
    // for a pipe a grandchild still holds (see `collect`).
    let stdout_reader = child.stdout.take().map(|mut pipe| {
        let (sent, received) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let mut buf = Vec::new();
            let truncated = drain_capped(&mut pipe, &mut buf).unwrap_or(false);
            let _ = sent.send((buf, truncated));
        });
        received
    });
    let stderr_reader = child.stderr.take().map(|mut pipe| {
        let (sent, received) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let mut buf = Vec::new();
            let _ = drain_capped(&mut pipe, &mut buf);
            let _ = sent.send(buf);
        });
        received
    });

    // The stdin write happens here, after the drains exist. Written first, a
    // child that filled its stderr pipe with nobody reading would stop
    // consuming stdin, and `write_all` would block before the timeout or the
    // cancel flag could fire.
    //
    // On its own thread, so a child that never reads its stdin cannot block the
    // deadline loop either; the writer ends when the child does.
    let stdin_writer = match (spec.stdin.clone(), child.stdin.take()) {
        (Some(bytes), Some(mut stdin)) => Some(std::thread::spawn(move || {
            // A child that exits without reading gives EPIPE, which is its
            // answer, not our failure.
            let _ = stdin.write_all(&bytes);
            drop(stdin);
        })),
        _ => None,
    };

    let deadline = std::time::Instant::now() + spec.timeout;
    // Woken the moment the child ends; otherwise only as often as a cancel or
    // an observer needs looking at.
    let exited = child::pidfd(child.id());
    let outcome = loop {
        match finished(spec, &mut child) {
            Some(Ok(status)) => break WaitOutcome::Exited(status),
            // A failed wait must not return early: that abandons the child.
            // Reap it and report the error instead.
            Some(Err(error)) => {
                terminate_or_kill_child_group(spec, &mut child);
                let _ = child.wait();
                break WaitOutcome::Failed(error);
            }
            None => {
                // Cancel is the caller's explicit intent: check it before the
                // deadline. Both take the same kill/wait path.
                if cancel.load(Ordering::Relaxed) {
                    terminate_or_kill_child_group(spec, &mut child);
                    let _ = child.wait();
                    break WaitOutcome::Cancelled;
                }
                if std::time::Instant::now() >= deadline {
                    terminate_or_kill_child_group(spec, &mut child);
                    let _ = child.wait();
                    break WaitOutcome::TimedOut;
                }
                if let Some(observe) = observer.as_mut()
                    && let Err(error) = observe()
                {
                    terminate_or_kill_child_group(spec, &mut child);
                    let _ = child.wait();
                    break WaitOutcome::Failed(error);
                }
                child::sleep_until_exit(
                    exited.as_ref(),
                    RUN_CHECK_INTERVAL
                        .min(deadline.saturating_duration_since(std::time::Instant::now())),
                    Duration::from_millis(20),
                );
            }
        }
    };

    // The child is finished either way by here, so the writer is unblocked: it
    // either wrote everything or took EPIPE. Joining keeps the thread from
    // outliving the call.
    if let Some(writer) = stdin_writer {
        let _ = writer.join();
    }
    // The readers end when every write end of their pipes closes, which a
    // grandchild outside a process group may hold long after the child: the
    // output waits until the deadline, a refusal only a moment.
    let status = match outcome {
        WaitOutcome::Exited(status) => status,
        WaitOutcome::TimedOut => return Err(BigSubprocessError::Timeout),
        WaitOutcome::Cancelled => return Err(BigSubprocessError::Cancelled),
        WaitOutcome::Failed(error) => return Err(BigSubprocessError::Io(error)),
    };
    let (Some((stdout_buf, stdout_truncated)), Some(stderr_buf)) = (
        collect(stdout_reader, deadline),
        collect(stderr_reader, deadline),
    ) else {
        return Err(BigSubprocessError::Timeout);
    };
    let code = status.code();
    Ok(BigSubprocessOutput {
        status: BigSubprocessStatus::Exited(code),
        stdout: stdout_buf,
        stdout_truncated,
        stderr: stderr_buf,
    })
}

/// What a reader thread sent once its pipe closed, or the empty value for a
/// pipe nobody captured; `None` when the pipe is still open at `deadline`.
fn collect<T: Default>(
    reader: Option<std::sync::mpsc::Receiver<T>>,
    deadline: std::time::Instant,
) -> Option<T> {
    let Some(reader) = reader else {
        return Some(T::default());
    };
    reader
        .recv_timeout(deadline.saturating_duration_since(std::time::Instant::now()))
        .ok()
}

/// The child's exit status once it has exited, reaping it; `None` while it runs.
///
/// A child in a process group of its own is seen exiting without being
/// reaped: its pid is the group's id until then, so the group's stragglers,
/// which may hold the output pipes, are killed before that id is freed for
/// reuse.
fn finished(
    spec: &BigSubprocessSpec,
    child: &mut std::process::Child,
) -> Option<std::io::Result<std::process::ExitStatus>> {
    #[cfg(unix)]
    if spec.unix_process_group {
        use rustix::process::{WaitId, WaitIdOptions, waitid};
        let options = WaitIdOptions::EXITED | WaitIdOptions::NOHANG | WaitIdOptions::NOWAIT;
        return match waitid(WaitId::Pid(Pid::from_child(child)), options) {
            Ok(None) => None,
            Ok(Some(_)) => {
                let _ = kill_process_group(Pid::from_child(child), Signal::KILL);
                Some(child.wait())
            }
            Err(error) => Some(Err(error.into())),
        };
    }
    child.try_wait().transpose()
}

fn terminate_or_kill_child_group(spec: &BigSubprocessSpec, child: &mut std::process::Child) {
    #[cfg(unix)]
    if spec.unix_process_group {
        let group = Pid::from_child(child);
        let _ = kill_process_group(group, Signal::TERM);
        std::thread::sleep(Duration::from_millis(100));
        let _ = kill_process_group(group, Signal::KILL);
        return;
    }
    let _ = child.kill();
}

/// Read `reader` to its end, keeping at most [`DEFAULT_MAX_CAPTURE_BYTES`];
/// `true` when bytes past that were dropped.
fn drain_capped<R: std::io::Read>(
    reader: &mut R,
    buf: &mut Vec<u8>,
) -> Result<bool, BigSubprocessError> {
    let mut chunk = [0u8; 8192];
    let mut truncated = false;
    loop {
        match reader.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => {
                let remaining = DEFAULT_MAX_CAPTURE_BYTES.saturating_sub(buf.len());
                truncated |= n > remaining;
                buf.extend_from_slice(&chunk[..n.min(remaining)]);
            }
            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(BigSubprocessError::Io(e)),
        }
    }
    Ok(truncated)
}

#[cfg(test)]
mod tests;

#[cfg(test)]
mod program_lookup_tests {
    use super::*;

    /// The name of a program that is not installed must not resolve, and a
    /// spec's own validation must not be mistaken for that answer.
    #[test]
    fn only_executables_count_as_installed() {
        let dir = std::env::temp_dir().join(format!("big-path-probe-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("a temporary directory");
        let runnable = dir.join("runnable");
        let plain = dir.join("plain");
        std::fs::write(&runnable, b"#!/bin/sh\n").expect("a file");
        std::fs::write(&plain, b"data").expect("a file");
        {
            use std::os::unix::fs::PermissionsExt as _;
            std::fs::set_permissions(&runnable, std::fs::Permissions::from_mode(0o755))
                .expect("mode");
            std::fs::set_permissions(&plain, std::fs::Permissions::from_mode(0o644)).expect("mode");
        }

        assert!(program_on_path(runnable.to_str().expect("utf-8")));
        assert!(!program_on_path(plain.to_str().expect("utf-8")));
        assert!(
            !program_on_path(dir.to_str().expect("utf-8")),
            "a directory"
        );
        assert!(!program_on_path(""), "an empty name is not a program");
        assert!(!program_on_path(
            dir.join("absent").to_str().expect("utf-8")
        ));
        let relative = std::path::Path::new(".")
            .join(relative_to_cwd(&dir))
            .join("runnable");
        assert!(program_on_path(relative.to_str().expect("utf-8")));

        // The validation a spec does is not an answer to "is it installed".
        assert!(
            BigSubprocessSpec::builder()
                .program("a-program-that-is-not-installed")
                .build()
                .try_resolved()
                .is_ok(),
            "try_resolved validates the name only; program_on_path is the file question"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// `dir`, spelled relative to the working directory.
    fn relative_to_cwd(dir: &std::path::Path) -> std::path::PathBuf {
        let cwd = std::env::current_dir().expect("a working directory");
        let mut relative = std::path::PathBuf::new();
        for _ in 1..cwd.components().count() {
            relative.push("..");
        }
        relative.push(dir.strip_prefix("/").expect("absolute"));
        relative
    }

    #[test]
    fn relative_path_entries_are_skipped() {
        let dir = std::env::temp_dir().join(format!("big-path-relative-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("a temporary directory");
        let tool = dir.join("tool");
        std::fs::write(&tool, b"#!/bin/sh\n").expect("a file");
        {
            use std::os::unix::fs::PermissionsExt as _;
            std::fs::set_permissions(&tool, std::fs::Permissions::from_mode(0o755)).expect("mode");
        }
        let relative = relative_to_cwd(&dir);
        let found = find_program_in("tool", relative.as_os_str());
        let absolute = find_program_in("tool", dir.as_os_str());
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(found, None);
        assert_eq!(absolute, Some(tool));
    }
}
